const AV_UNITS=[
 {id:'karten',title:'Eine Flugkarte lesen',tag:'RAUM & ORIENTIERUNG',image:'flugkarte',lead:'Eine Flugkarte zeigt mehr als Wege: Sie ordnet Gelände, Höhen, Einrichtungen und Regeln.',blocks:[
 ['Vier Karten, vier Fragen','Eine Übersichtskarte hilft beim räumlichen Einordnen. Eine Sichtflugkarte verbindet Gelände mit Luftfahrtinformationen. Eine Streckenkarte für Instrumentenflug stellt unter anderem Routen und Navigationspunkte dar. Eine Flugplatzkarte zeigt Start- und Landebahnen sowie Rollwege. Frage zuerst: Für welche Aufgabe wurde diese Darstellung angefertigt?'],
 ['Die dritte Dimension','Eine gezeichnete Grenze allein reicht nicht. Lufträume haben auch Unter- und Obergrenzen. Zwei Flugzeuge können auf einer flachen Karte unmittelbar nebeneinander erscheinen und doch in unterschiedlichen Höhen fliegen. Umgekehrt kann ein zweidimensionales Bild einen Höhenkonflikt verbergen.'],
 ['Die vier Leseschritte','1. Titel, Ort und Ausgabedatum prüfen. 2. Massstab und Einheiten bestimmen. 3. Symbole mithilfe der zugehörigen Legende lesen. 4. Fehlende Informationen notieren: Wetter? Zeitliche Gültigkeit? Tatsächlicher Flugweg? Eine eingezeichnete Route beweist noch nicht, dass ein Flugzeug sie geflogen ist.'],
 ['Originalmaterial erkunden','Die unten gezeigte US-Karte dient dem Vergleich von Kartensprache. Sie zeigt weder München noch den Flug aus «Terror». Für Deutschland öffnest du das DFS-Luftfahrthandbuch und suchst nach dem Flugplatz München (EDDM), insbesondere den Flugplatzkarten. Aktuelle Publikationen beschreiben nicht automatisch den Zustand des fiktiven Tattags.']
 ],source:['charts','aip','aup'],task:'Finde in der Beispielkarte drei Arten von Informationen. Notiere jeweils: sichtbares Zeichen → vermutete Bedeutung → nötige Legende. Welche Informationen bräuchtest du zusätzlich, um Kochs Lage räumlich zu rekonstruieren?',check:['Beweist eine eingezeichnete Flugroute den tatsächlichen Verlauf?',['Ja, eine Karte dokumentiert immer den wirklichen Flug.','Nein. Dafür braucht es zeitbezogene Beobachtungen oder Aufzeichnungen.','Nur wenn die Karte farbig ist.'],1,'Eine Karte beschreibt eine Darstellung oder Planung. Erst Beobachtungsdaten belegen den tatsächlichen Weg. Prüfe Kartentyp und Gültigkeit.','charts']},
 {id:'tower',title:'Tower, Approach, Center',tag:'MENSCHEN & ARBEITSPLÄTZE',image:'zuerich',lead:'Flugsicherung ist verteilte Arbeit. Der weithin sichtbare Tower ist nur ein Teil davon.',blocks:[
 ['Tower: nah am Flughafen','Towerlotsinnen und -lotsen organisieren Verkehr auf den Start- und Landebahnen, Rollwegen und im unmittelbaren Flughafenumfeld. Der Blick aus dem Fenster verbindet sich mit technischen Anzeigen. Der Tower erteilt beispielsweise Start- und Landefreigaben.'],
 ['Approach und Center','Die An- und Abflugkontrolle begleitet den Übergang zwischen Flughafen und Streckenflug. Centerlotsen bearbeiten grössere Luftraumbereiche auf ihren Anzeigen. Sektoren und Zuständigkeiten werden übergeben; ein Flug wird nicht durchgehend von derselben Person betreut.'],
 ['Eine Übergabe ist eine Informationsaufgabe','Denke eine Übergabe als Staffel: Welche Maschine? Welche Position? Welche Höhe? Welche Freigabe? Welche Besonderheit? Eine neue zuständige Stelle muss anschliessen können, ohne aus einer Lücke eine Gewissheit zu machen.'],
 ['Brücke zum Drama','Lauterbach ist im Stück ein militärischer Zeuge aus dem Lagezentrum. Er ist nicht einfach «der Mann im Flughafentower». Prüfe, welche Information er selbst beobachtet, welche ihm gemeldet wird und welche er erst vor Gericht erklärt. PDF-S. 17–42.']
 ],source:['dfs'],task:'Vergleiche Towerfoto und Centerfoto. Nenne zwei unterschiedliche Informationszugänge. Zeichne danach für Lauterbach eine Kette aus Quelle, Meldung und Aussage – mit einer offenen Stelle.',check:['Wer ist Lauterbach im Drama?',['Der zivile Towerlotse von München.','Ein militärischer Zeuge aus dem Lagezentrum.','Der Flugkapitän der Passagiermaschine.'],1,'Lauterbach berichtet aus der militärischen Organisation. Seine Funktion darf nicht mit ziviler Platzkontrolle verwechselt werden. Referenz: Drama, PDF-S. 17–42; DFS erklärt die zivilen Arbeitsplätze.','dfs']},
 {id:'radar',title:'Was ein Lagebild weiss',tag:'DATEN & UNSICHERHEIT',image:'center',lead:'Ein Symbol kann eine Maschine repräsentieren. Es zeigt keine Gedanken und keine moralische Entscheidung.',blocks:[
 ['Primärradar','Primärradar dient der nichtkooperativen Ortung: Es ist nicht auf eine passende Transponderantwort des erfassten Flugzeugs angewiesen. Das bedeutet nicht, dass damit überall und jederzeit jedes Detail sicher feststeht. Abdeckung und Leistungsfähigkeit bleiben relevant.'],
 ['Sekundärradar und Transponder','Ein Transponder antwortet auf Abfragen. Klassische SSR-Codes bestehen aus vier Ziffern, jeweils von 0 bis 7. Sie unterstützen die Identifizierung. Je nach System und Ausstattung werden weitere Daten verarbeitet. Ein Kennzeichen auf dem Bildschirm ist etwas anderes als eine direkte Beobachtung des Cockpits.'],
 ['Drei verschiedene Sätze','«Das Flugzeug hat seinen Kurs verändert» beschreibt eine beobachtete Bewegung. «Es könnte auf ein Ziel zusteuern» ist eine Deutung. «Es wird dort sicher einschlagen» behauptet einen zukünftigen Ausgang. Untersuche, welche Zusatzbelege für jeden Schritt nötig wären.'],
 ['Achtung Rückschau','Wer den Ausgang kennt, überschätzt leicht, wie eindeutig die Situation zuvor war. Im Prozess musst du den Wissensstand zum jeweiligen Zeitpunkt rekonstruieren. Die spätere SMS-Aussage Meisers wird dadurch nicht automatisch zu Kochs Wissen vor dem Abschuss. PDF-S. 51–52 und 65–73.']
 ],source:['radar','transponder'],task:'Beschreibe das interaktive Lagebild zuerst ausschliesslich mit beobachtbaren Daten. Formuliere danach eine Vermutung – und eine Frage, die diese Vermutung prüfen könnte.',check:['Ein Radarsymbol zeigt einen Kurswechsel. Was folgt daraus?',['Die Absicht der Menschen an Bord steht fest.','Die Bewegung ist ein Hinweis; die Absicht benötigt weitere Belege.','Die Maschine existiert nur virtuell.'],1,'Ortung liefert Informationen über Bewegung und Position. Die Absicht ist eine zusätzliche Interpretation. Referenz: Abschnitt «Drei verschiedene Sätze» und EUROCONTROL zur Ortung.','radar']},
 {id:'zeit',title:'Wie viel Zeit bleibt?',tag:'ZEIT & GRÖSSENORDNUNGEN',image:'muenchen',lead:'Rechne Grössenordnungen nach, bevor du aus «wenigen Minuten» eine zwingende Schlussfolgerung machst.',blocks:[
 ['Distanz und Geschwindigkeit','Eine nautische Meile (NM) entspricht 1,852 Kilometern. Ein Knoten (kt) bedeutet eine nautische Meile pro Stunde. Für eine konstante Geschwindigkeit über Grund gilt: Zeit in Minuten = Distanz in NM ÷ Geschwindigkeit in kt × 60.'],
 ['Ein Rechenbeispiel','60 NM bei 360 kt ergeben 10 Minuten. Bei 480 kt sind es 7,5 Minuten. Das ist ein idealisiertes Rechenmodell: Es kennt keine Kurve, Beschleunigung, Verzögerung, Höhenänderung oder wechselnde Route. Die Zahlen hier sind frei gewählte Übungswerte, keine rekonstruierten Flugdaten des Stücks.'],
 ['Nicht dieselbe Uhr','Zeit bis zu einem möglichen Ereignis, Zeit zum Entscheiden, Zeit zum Übermitteln und Zeit zum Handeln sind verschiedene Grössen. Eine Räumungsdauer beginnt nicht schon in dem Moment, in dem irgendwo eine Gefahr erkannt wird.'],
 ['Was die Rechnung nicht entscheidet','Auch eine genaue Zeitrechnung beantwortet nicht, welche Handlung rechtlich erlaubt ist. Und eine längere Frist garantiert keine gelungene Rettung. Nutze das Modell, um Fragen zu schärfen, nicht um aus einer Zahl ein automatisches Urteil abzuleiten. Vergleiche die Diskussion über die unterlassene Räumung, PDF-S. 35–42.']
 ],source:['charts'],task:'Berechne zwei Varianten. Verändere zuerst nur die Distanz, dann nur die Geschwindigkeit. Welche zusätzlichen Angaben wären nötig, um die Räumungsfrage im Drama zu bewerten?',check:['60 NM bei 360 kt dauern im Modell …',['10 Minuten.','6 Minuten.','60 Minuten.'],0,'60 ÷ 360 × 60 = 10 Minuten. Gemeint ist konstante Geschwindigkeit über Grund auf einer gleichbleibenden Strecke. Referenz: Rechenformel in diesem Abschnitt.','charts']},
 {id:'kommunikation',title:'Melden, verstehen, rückfragen',tag:'SPRACHE & HUMAN FACTORS',image:'simulator',lead:'Eine präzise Meldung trennt Beobachtung, Quelle, Zeitpunkt und Vermutung.',blocks:[
 ['Sprache als Sicherheitsarbeit','Im Luftverkehr müssen Beteiligte Informationen unter Zeitdruck verstehen. Für unser Lernmodell übertragen wir das in vier Felder: Was wurde beobachtet? Von wem oder welchem System stammt es? Wann? Was ist noch unklar? Diese Unterrichtsstruktur ist kein reales Sprechfunkverfahren.'],
 ['Ein erfundenes Übungsprotokoll','Schwach: «Das Flugzeug macht etwas Gefährliches.» Präziser: «Um 14:06 zeigt unsere Anzeige eine Abweichung vom zuvor dargestellten Kurs. Ein Grund ist uns nicht bekannt.» Die zweite Meldung macht ihre Wissensgrenze sichtbar. Beide Sätze sind didaktisch erfunden, keine Zitate aus Film oder Funk.'],
 ['Drei Denkfallen','Bestätigungsfehler: Man sucht nur Hinweise auf die erste Vermutung. Tunnelblick: Eine drängende Aufgabe verdrängt andere relevante Informationen. Rückschaufehler: Nachher erscheint eine Entwicklung vorhersehbarer als zuvor. Nutze diese Begriffe als Prüffragen, nicht als Ferndiagnose einzelner Figuren.'],
 ['Gegenmassnahmen im Lernen','Lass eine zweite Person die Meldung zusammenfassen. Markiert gemeinsam, was sicher, berichtet oder offen ist. Sucht einen möglichen Gegenbeleg. Stellt die Frage: Welche neue Information würde unsere Einschätzung tatsächlich verändern?']
 ],source:['dfs'],task:'Schreibe eine Lageübergabe in vier Sätzen: Beobachtung, Quelle, Zeitpunkt, offene Frage. Überarbeite danach eine Formulierung, die mehr Sicherheit behauptet, als dein Beleg trägt.',check:['Welche Meldung ist in unserer Übung am sorgfältigsten?',['Alle wissen doch, was los ist.','Die Anzeige zeigt eine Abweichung; der Grund ist unklar.','Keine Antwort bedeutet sicher einen Angriff.'],1,'Die zweite Meldung trennt eine Beobachtung von unbekannten Gründen. Referenz: «Ein erfundenes Übungsprotokoll». Das ist eine Lernübung, kein amtliches Funkmuster.','dfs']},
 {id:'alarmrotte',title:'Abfangen heisst nicht abschiessen',tag:'MILITÄR & ZUSTÄNDIGKEIT',image:'muenchen',lead:'Luftraumüberwachung, Identifizierung und Waffeneinsatz sind unterschiedliche Fragen.',blocks:[
 ['Was eine Alarmrotte tut','Die Bundeswehr beschreibt die Alarmrotte als bereitgehaltene Kampfflugzeuge zur Reaktion auf Auffälligkeiten im Luftraum. Zum Auftrag können visuelles Identifizieren, Beobachten und Begleiten gehören. Der militärische Fachbegriff lautet Quick Reaction Alert (QRA).'],
 ['COMLOSS und Renegade','COMLOSS bezeichnet einen Kommunikationsverlust. Das ist für sich genommen kein Beweis für eine Entführung. Ein Renegade-Verdacht betrifft den möglichen Missbrauch eines zivilen Luftfahrzeugs als Waffe. Dafür werden weitere Informationen und eine besondere Bewertung benötigt.'],
 ['Wer darf was entscheiden?','Zivile Flugsicherung, militärische Führung und politische Verantwortung haben unterschiedliche Aufgaben. Ein Fluglotse erteilt keine allgemeine rechtliche Erlaubnis, Menschen zu töten. Eine technische Fähigkeit und eine militärische Meldung ersetzen die Prüfung einer Befugnis nicht.'],
 ['Gegenwart und literarischer Fall','Die hier verlinkte Bundeswehrdarstellung erklärt heutige Aufgaben. Der Tatvorwurf im Drama gehört zu einer fiktionalen Konstellation. Leite aus gegenwärtigen Organisationsbeschreibungen keinen historischen Abschussbefehl ab. Im Stück handelt Koch gegen den ausdrücklich mitgeteilten Nicht-Abschussbefehl; prüfe PDF-S. 26–32.']
 ],source:['policing'],task:'Lege drei Spalten an: beobachten/identifizieren, eine Gefahr bewerten, einen Eingriff rechtlich verantworten. Ordne Aussagen aus Lauterbachs Vernehmung zu. Wo bleiben Zuständigkeiten oder Informationen unklar?',check:['Ein Kommunikationsverlust beweist …',['… für sich allein eine Entführung.','… noch keine bestimmte Ursache oder Angriffsabsicht.','… dass jede Ortung unmöglich ist.'],1,'Funkkontakt, Ortung und Absicht sind verschiedene Fragen. Ein COMLOSS-Ereignis braucht Abklärung. Referenz: Bundeswehr, Air Policing; Abschnitt «COMLOSS und Renegade».','policing']},
 {id:'wetter',title:'Wetter, Sicht und Flugbedingungen',tag:'UMWELT & GRENZEN',image:'zuerich',lead:'Eine Position auf der Karte sagt wenig darüber, unter welchen Bedingungen geflogen und beobachtet wird.',blocks:[
 ['Beobachtung oder Vorhersage?','Ein METAR ist eine standardisierte Flugplatz-Wetterbeobachtung. Ein TAF ist eine Flugplatz-Wettervorhersage für einen angegebenen Zeitraum. Beides ist räumlich und zeitlich gebunden; eine Vorhersage ist kein Beweis, dass etwas genau so eingetreten ist.'],
 ['Vier Faktoren im Blick','Wind verändert die Bewegung über Grund gegenüber der Bewegung durch die Luft. Sicht und Wolken beeinflussen, was visuell erkennbar ist. Gewitter können Umwege und zusätzliche Belastung verursachen. Vereisungsbedingungen können besondere Risiken bedeuten. Für einen konkreten Flug genügt deshalb keine allgemeine Wetterbeschreibung.'],
 ['Keine nachträglichen Erfindungen','Wir ergänzen den Fall nicht mit erfundenem Nebel oder Gewitter. Wenn der Text keine tragfähige Angabe macht, notierst du «nicht belegt». Ein Foto eines Towers bei Sonne belegt ebenfalls nicht die Wetterlage am Tattag.'],
 ['Ein Transferauftrag','Formuliere zwei ausdrücklich hypothetische Varianten: einmal gute, einmal eingeschränkte Sicht. Welche Beobachtung wäre jeweils schwieriger? Welche rechtliche Frage bliebe trotzdem bestehen?']
 ],source:['weather'],task:'Erstelle eine Liste «beobachtet / vorhergesagt / im Text nicht angegeben». Begründe, weshalb Wetterinformationen aus einem anderen Ort oder Zeitpunkt keine Lücke im Tatablauf schliessen.',check:['Ein TAF ist …',['… eine Wettervorhersage für einen Flugplatz und Zeitraum.','… ein Protokoll aller tatsächlichen Flugbewegungen.','… ein militärischer Abschussbefehl.'],0,'TAF steht hier für Terminal Aerodrome Forecast. Es handelt sich um eine Vorhersage; METAR beschreibt eine Beobachtung. Referenz: FAA, Aviation Weather Handbook, Produkte METAR und TAF.','weather']},
 {id:'prozess',title:'Vom Lagebild zum Gericht',tag:'BEWEISE & URTEIL',image:'center',lead:'Technisches Wissen hilft bei der Tatsachenklärung. Über Recht und Schuld entscheidet es nicht allein.',blocks:[
 ['Eine Beweiskette aufbauen','Welche Quelle stützt eine Angabe? Ist sie unmittelbar beobachtet, technisch aufgezeichnet oder von jemandem berichtet? Welchen Zeitpunkt betrifft sie? Welche Deutung wird darauf aufgebaut? Halte diese Ebenen in deiner Prozessakte auseinander.'],
 ['Vier gute Fragen an Lauterbach','Welche Angabe haben Sie selbst wahrgenommen? Von welcher Stelle kam die Meldung? Was war Koch zu diesem Zeitpunkt mitgeteilt worden? Welche Alternative wurde von wem geprüft? Formuliere offen und ohne die gewünschte Antwort vorwegzunehmen.'],
 ['Die rechtliche Grenze','Das Bundesverfassungsgericht verwarf 2006 die damalige Abschussermächtigung. Beim gezielten Töten unbeteiligter Menschen an Bord hob es Menschenwürde und Lebensrecht hervor. Das ist der rechtliche Hintergrund des Dramas; ein technischer Zeitvorteil hebt diese Prüfung nicht auf.'],
 ['Deine Sachverständigen-Notiz','Schreibe keine fertige Verurteilung und keinen automatischen Freispruch. Liefere dem Gericht vielmehr drei belegte Angaben, zwei verbleibende Unsicherheiten und eine Frage zur rechtlichen Einordnung. Markiere jede Modellannahme ausdrücklich.']
 ],source:['court','policing'],task:'Erstelle eine sachverständige Kurznotiz für euren Multiplayer-Prozess. Verbinde eine technische Information mit einer konkreten Textstelle und erkläre ihre Grenze. Übertrage sie anschliessend bewusst in den gemeinsamen Chat.',check:['Was kann eine korrekte Zeitrechnung leisten?',['Sie ersetzt die Prüfung von Menschenwürde und Schuld.','Sie klärt eine Annahme unter angegebenen Bedingungen.','Sie beweist automatisch den Freispruch.'],1,'Ein Modell klärt nur die in ihm enthaltenen Annahmen. Tatsachen, Befugnisse und persönliche Schuld bleiben getrennte Prüfungsschritte. Referenz: dieser Abschnitt und BVerfG 2006.','court']}
];
const AV_GLOSSARY=[
 ['AIP','Aeronautical Information Publication: Luftfahrthandbuch mit dauerhaft wichtigen Angaben; Ergänzungen und Änderungen gehören zur Quellenprüfung.','aip'],
 ['Flugplatzkarte','Zeigt die Anlage eines Flugplatzes, etwa Bahnen und Rollwege. Nicht mit einer Streckenkarte verwechseln.','charts'],
 ['VFR / IFR','Sichtflugregeln / Instrumentenflugregeln. Die Regelart ist keine Aussage darüber, ob ein Flug moralisch oder rechtlich zulässig ist.','charts'],
 ['NM / kt','Nautische Meile / Knoten. 1 NM = 1,852 km; 1 kt = 1 NM pro Stunde.','charts'],
 ['UTC','Koordinierte Weltzeit. Vor dem Vergleich zweier Uhrzeiten prüfen, ob beide dieselbe Zeitbasis verwenden.','charts'],
 ['MSL','Mean Sea Level: mittlerer Meeresspiegel als Höhenbezug. Eine Höhenzahl braucht immer ihre Bezugsangabe.','charts'],
 ['Tower','Platzkontrolle am Flughafen; Schwerpunkt auf Flughafenverkehr und unmittelbarem Umfeld.','dfs'],
 ['Approach','Anflugkontrolle; verbindet den Bereich des Flughafens mit dem Streckenverkehr.','dfs'],
 ['Center','Kontrollzentrale für zugeordnete Luftraumbereiche und Sektoren.','dfs'],
 ['Staffelung','Vorgeschriebene Abstände zwischen Luftfahrzeugen herstellen und erhalten; konkrete Anforderungen hängen vom Verfahren ab.','dfs'],
 ['Primärradar','Ortung ohne notwendige Kooperation eines Transponders im Flugzeug.','radar'],
 ['SSR / Transponder','Sekundärradar arbeitet mit Antworten eines Geräts an Bord. Identifikationsdaten helfen, Flugspuren zuzuordnen.','transponder'],
 ['COMLOSS','Kommunikationsverlust. Eine Ursache muss erst abgeklärt werden.','policing'],
 ['QRA / Alarmrotte','Quick Reaction Alert: militärische Bereitschaft zur Reaktion auf Luftlageereignisse.','policing'],
 ['Renegade-Verdacht','Verdacht auf einen möglichen Missbrauch eines zivilen Luftfahrzeugs als Waffe. Keine automatische Erlaubnis für einen beliebigen Eingriff.','policing'],
 ['METAR / TAF','Flugplatz-Wetterbeobachtung / Flugplatz-Wettervorhersage. Zeitpunkt und Gültigkeit mitlesen.','weather'],
 ['Beobachtung / Prognose','Eine Feststellung über ein beobachtetes Ereignis / eine Aussage über eine erwartete Entwicklung. Didaktische Unterscheidung für die Beweisprüfung.','radar'],
 ['Modellannahme','Für eine Rechnung gesetzte Voraussetzung. Hier beispielsweise konstante Geschwindigkeit; kein zusätzlicher Fakt des Dramas.','charts']
];
const avRef=k=>`<a href="${AV_SOURCES[k][1]}" target="_blank" rel="noopener noreferrer">${AV_SOURCES[k][0]} ↗</a>`;
const avImagePath=k=>'media/aviatik/'+k+(['simulator','zuerich'].includes(k)?'-preview':'')+'.jpg';
function avImage(k,hero=false){const m=AV_IMAGES[k];return `<figure class="av-photo ${hero?'av-photo-hero':''}"><a href="media/aviatik/${k}.jpg" target="_blank" rel="noopener" aria-label="${m[0]} gross öffnen"><img src="${avImagePath(k)}" alt="${m[0]}" loading="${hero?'eager':'lazy'}"></a><figcaption><strong>${m[0]}</strong><span>${m[1]} · <a href="https://commons.wikimedia.org/wiki/File:${encodeURIComponent(m[2])}" target="_blank" rel="noopener">Bildquelle</a> · <a href="${m[4]}" target="_blank" rel="noopener">${m[3]}</a>. Bildinhalt unverändert; Vorschau teils beschnitten. Original über das Bild öffnen.</span></figcaption></figure>`;}
function avQuiz(u){const chosen=state.answers['aviatik-'+u.id];return `<section class="av-check card"><span class="eyebrow">SOFORTFEEDBACK</span><h2>${u.check[0]}</h2><div class="options">${u.check[1].map((a,i)=>`<button class="secondary" data-av-check="${u.id}" data-av-option="${i}" aria-pressed="${chosen===i}">${a}</button>`).join('')}</div><div id="av-feedback-${u.id}" role="status">${Number.isInteger(chosen)?avQuizFeedback(u,chosen):''}</div></section>`;}
function avQuizFeedback(u,n){return `<div class="callout"><b>${n===u.check[2]?'Richtig eingeordnet.':'Noch einmal unterscheiden.'}</b><p>Richtige Antwort: ${u.check[1][u.check[2]]}</p><p>${u.check[3]}</p><p>${avRef(u.check[4])}</p></div>`;}
function aviation(id){const u=AV_UNITS.find(x=>x.id===id);if(id&&!u)return missing();if(u)return `<div id="av-root" data-aviation="${u.id}"><p class="breadcrumb"><a href="#aviatik">Aviatik · Lage & Verantwortung</a> / ${u.title}</p>${head(u.tag,u.title,u.lead)}${avImage(u.image)}<nav class="av-unit-nav" aria-label="Aviatische Stationen">${AV_UNITS.map((x,i)=>`<a href="#aviatik/${x.id}" ${x.id===id?'aria-current="page"':''}>${i+1}. ${x.title}</a>`).join('')}</nav>${id==='karten'?avChartLab():id==='radar'?avRadar():id==='zeit'?avTimeLab():''}<div class="grid">${u.blocks.map(([t,b])=>`<section class="card"><h2>${t}</h2><p>${b}</p></section>`).join('')}</div>${id==='tower'?`<div class="av-gallery">${avImage('center')}${avImage('muenchen')}</div>`:id==='kommunikation'?avDispatch():id==='prozess'?avTimeline():''}<section class="section card"><h2>Dein Transfer zum Stück</h2><p>${u.task}</p>${note('aviatik-'+id,u.title+' · Transfer','Beobachtung → Beleg → Schlussfolgerung → Grenze')}${details('Deine Begründung selbst prüfen','Habe ich eine Quelle und einen Zeitpunkt genannt? Trenne ich Tatsachen, Berichte und Annahmen? Habe ich eine Unsicherheit benannt? Ein Fachwort allein ist noch kein Beleg.')}<p class="source">Fachquellen: ${u.source.map(avRef).join(' · ')}</p></section>${avQuiz(u)}<div class="av-next"><a class="button secondary" href="#aviatik">← Übersicht</a><a class="button" href="#lektuere/lauterbach">Lauterbach neu lesen →</a>${id==='prozess'?'<a class="button" href="spielraum/">In den Multiplayer-Prozess →</a>':''}</div></div>`;
return `<div id="av-root" data-aviation="overview"><div class="av-intro"><span class="eyebrow">NEUE EINHEIT · AVIATIK</span><h1>Den Luftraum lesen.<br>Die Verantwortung verstehen.</h1><p class="lead">Flugkarten, Towerperspektiven und technische Hintergründe zum Fall Lars Koch. Acht offene Stationen zum Erkunden, Rechnen und begründeten Nachfragen.</p></div><section class="section card"><span class="eyebrow">NEU · TECHNIKLABOR</span><h2>Eurofighter und seine Bewaffnung · Airbus A320</h2><p>Beschriftete Flugzeugschemata, Triebwerke, Flugsteuerung und Redundanz. Beim Eurofighter: Bordkanone, Lenkflugkörper und die im Stück eingesetzte Sidewinder mit Demofilm. Mit Textbelegen und technischen Vertiefungen.</p><a class="button" href="technik/">Das Techniklabor öffnen →</a></section>${avImage('simulator',true)}<div class="av-labels"><span>REALE FACHQUELLEN</span><span>FIKTIVER DRAMENTEXT</span><span>GEKENNZEICHNETE LERNMODELLE</span></div><p class="callout">Die Fotos zeigen reale Arbeitsplätze oder einen Simulator, keine Schauplätze des Films. Unsere Lagegrafik und Rechenwerte sind Unterrichtsmodelle, keine Rekonstruktion eines tatsächlichen Fluges und keine Navigationsunterlagen.</p><section class="section"><h2>Deine acht Stationen</h2><div class="grid three">${AV_UNITS.map((u,i)=>`<a class="card card-link av-unit-card" href="#aviatik/${u.id}"><img src="${avImagePath(u.image)}" alt="${AV_IMAGES[u.image][0]}" loading="lazy"><span class="number">0${i+1}</span><h3>${u.title}</h3><p>${u.lead}</p><span class="meta">${u.tag}</span></a>`).join('')}</div></section>${avRadar()}${avTimeLab()}<section class="section"><span class="eyebrow">TOWERIMPRESSIONEN</span><h2>Sehen, was andere sehen</h2><p>Vergleiche Fensterblick, Anzeigen und Zusammenarbeit. Welche Informationen kommen in welchem Raum zusammen?</p><div class="av-gallery">${avImage('muenchen')}${avImage('zuerich')}${avImage('center')}</div></section>${avTimeline()}<section class="section card"><h2>Kleines Luftfahrtlexikon</h2><label class="field"><span>Begriff suchen</span><input id="av-glossary-search" type="search" placeholder="Zum Beispiel: Radar, Tower, Wetter …"></label><div id="av-glossary">${avGlossary('')}</div></section><section class="section card"><h2>Originalquellen und Kartenportale</h2><p>Recherche: 30. September 2026. Die Fachquellen erklären Luftfahrt; die Verbindung zum Drama und die Übungen sind didaktische Ausarbeitungen.</p><div class="av-sources">${Object.keys(AV_SOURCES).map(k=>`<p>${avRef(k)}</p>`).join('')}</div><p>Bildnachweise stehen an den grossen Bildern und auf jeder Station. ${Object.entries(AV_IMAGES).map(([k,m])=>`<a href="https://commons.wikimedia.org/wiki/File:${encodeURIComponent(m[2])}" target="_blank" rel="noopener">${m[0]} · ${m[1]} · ${m[3]}</a>`).join('<br>')}</p></section><section class="card"><h2>Zurück in den Gerichtssaal</h2><p>Nutze dein neues Wissen, um bessere Fragen zu stellen: Wer wusste was, wann, aufgrund welcher Quelle?</p><p><a href="#lektuere/lauterbach">Lauterbachs Aussage</a> · <a href="#lektuere/evakuierung">Die Räumungsfrage</a> · <a href="#recht">Recht und Urteil</a> · <a href="spielraum/">Gemeinsamer Prozess</a></p>${note('aviatik-fazit','Aviatik · Was ändert sich an meinem Urteil?','Ein neu verstandener Zusammenhang · eine offene Frage · eine Grenze technischer Erklärungen')}</section></div>`;}
function avGlossary(query){const q=query.toLocaleLowerCase('de');const found=AV_GLOSSARY.filter(x=>(x[0]+' '+x[1]).toLocaleLowerCase('de').includes(q));return found.length?found.map(([t,b,s])=>`<details><summary>${t}</summary><p>${b}</p><p class="source">${avRef(s)}</p></details>`).join(''):'<p role="status">Kein passender Begriff. Suche beispielsweise nach «Radar» oder «Zeit».</p>';}
function avChartLab(){return `<section class="section card"><h2>Kartenwerkstatt: Original und Modell</h2><p><b>Originalbeispiel:</b> Die FAA-Karte oben zeigt Anchorage (Alaska), Ausgabe vom 21. März 2024, Massstab 1:500’000. Öffne das Bild gross und suche einen Flugplatznamen, eine Höhenangabe und eine Begrenzung. Symbole sind mit der zugehörigen US-Legende zu lesen.</p><div class="grid"><div><h3>Deutschland erkunden</h3><p>${avRef('aip')}</p><p>Suche München / EDDM und eine Flugplatzkarte. Vergleiche Bahnen und Rollwege mit dem Towerfoto. Übernimm keine vermeintliche Flugroute für Koch aus dieser Karte.</p></div><div><h3>Zeitliche Grenzen entdecken</h3><p>${avRef('aup')}</p><p>WebAUP zeigt ausgewählte Luftraumaktivierungen und beansprucht keine Vollständigkeit. Welche Ergänzungen nennt das Portal selbst? Warum ist «nicht auf meiner Karte» kein Beweis für «existiert nicht»?</p></div></div><p class="source">Legendenhilfe: ${avRef('charts')}. Das alte Kartenbeispiel bleibt als datiertes Lernmaterial erhalten.</p></section>`;}
const AV_LAYERS={position:['Position','Gezeigt wird eine erfundene Position im Unterrichtsmodell. Sie sagt nichts über die Absicht der Besatzung aus.'],track:['Bewegung','Die gestrichelte Spur verbindet erfundene frühere Positionen. Sie ist kein Flugplan und keine Tatortrekonstruktion.'],prediction:['Prognose','Die helle Verlängerung setzt den Kurs gedanklich fort. Eine Gerade in die Zukunft ist eine Annahme, kein beobachteter Ausgang.']};
function avRadar(){return `<section class="section av-radar"><div class="section-head"><div><span class="eyebrow">INTERAKTIVES LAGEBILD · FREI ERFUNDEN</span><h2>Was zeigt der Bildschirm?</h2></div><span class="tag">Kein Live-Radar</span></div><div class="av-map-layout"><div><svg viewBox="0 0 700 410" role="img" aria-labelledby="av-map-title av-map-desc"><title id="av-map-title">Schematisches Lagebild mit drei Informationsebenen</title><desc id="av-map-desc">Erfundener Sektor mit Flugplatz A und Beobachtungspunkt B. Eine Position, eine vergangene Spur und eine angenommene Kursverlängerung lassen sich getrennt betrachten. Ohne geografischen Massstab.</desc><defs><pattern id="av-grid" width="50" height="50" patternUnits="userSpaceOnUse"><path d="M 50 0 L 0 0 0 50" fill="none" stroke="#294e58" stroke-width="1"/></pattern></defs><rect width="700" height="410" fill="#112b35"/><rect width="700" height="410" fill="url(#av-grid)"/><g fill="none" stroke="#325660"><circle cx="350" cy="205" r="90"/><circle cx="350" cy="205" r="170"/></g><path d="M 90 90 L 210 100 L 250 330 L 90 310Z" fill="#1d4750" stroke="#69a4ad" stroke-dasharray="6 6"/><text x="95" y="70" fill="#a9ccd1" font-size="16">Sektor A · schematisch</text><path d="M105 220L170 180" stroke="#fff" stroke-width="8"/><text x="78" y="255" fill="#fff" font-size="17">Flugplatz A</text><g id="av-track" hidden><path d="M200 290L265 260L340 230L405 205" fill="none" stroke="#80caca" stroke-width="3" stroke-dasharray="8 7"/></g><g id="av-prediction" hidden><path d="M405 205L610 126" fill="none" stroke="#f4c16d" stroke-width="3" stroke-dasharray="4 7"/><text x="436" y="112" fill="#f4c16d" font-size="16">angenommene Fortsetzung</text></g><circle cx="405" cy="205" r="8" fill="#dfef78"/><path d="M393 208L418 200L401 220Z" fill="#dfef78"/><text x="418" y="230" fill="#dfef78" font-size="17">MODELL 01</text><circle cx="610" cy="126" r="6" fill="#fff"/><text x="545" y="162" fill="#fff" font-size="16">Punkt B</text><text x="25" y="383" fill="#a9ccd1" font-size="14">Keine reale Geografie · kein Massstab · keine echten Flugdaten</text></svg></div><div class="av-map-tools"><div class="pill-row" role="group" aria-label="Informationsebene">${Object.entries(AV_LAYERS).map(([k,[t]],i)=>`<button data-av-layer="${k}" aria-pressed="${i===0}">${t}</button>`).join('')}</div><p id="av-layer-info" aria-live="polite">${AV_LAYERS.position[1]}</p><h3>Deine Kontrollfrage</h3><p>Welche Information fehlt, bevor du aus einer Bewegung eine Absicht ableitest?</p><a href="#aviatik/radar">Ortung genauer verstehen →</a></div></div></section>`;}
function avCalculate(nm,kt,delay){if(!Number.isFinite(nm)||!Number.isFinite(kt)||!Number.isFinite(delay)||nm<1||nm>200||kt<120||kt>600||delay<0||delay>20)return null;const flight=nm/kt*60;return {flight,remaining:Math.max(0,flight-delay),exceeded:delay>=flight};}
function avTimeLab(){return `<section class="section card av-time"><span class="eyebrow">MODELLLABOR · KEINE FLUGDATEN AUS DEM STÜCK</span><h2>Distanz wird zu Zeit</h2><p>Ändere die Übungswerte. Die Rechnung nimmt eine gleichbleibende Strecke und konstante Geschwindigkeit über Grund an.</p><div class="grid three"><label class="field"><span>Restdistanz (NM)</span><input data-av-calc id="av-distance" type="number" min="1" max="200" value="60"></label><label class="field"><span>Geschwindigkeit über Grund (kt)</span><input data-av-calc id="av-speed" type="number" min="120" max="600" value="360"></label><label class="field"><span>Zeit für Übermittlung und Vorbereitung (min)</span><input data-av-calc id="av-delay" type="number" min="0" max="20" step="0.5" value="2"></label></div><div id="av-calculation" class="av-result" role="status">${avCalculationHTML(avCalculate(60,360,2))}</div><p class="notice">«Restzeit» ist nur die Differenz in diesem Modell. Daraus folgt weder, dass eine Räumung gelingt, noch, dass ein Eingriff erlaubt ist.</p><a href="#aviatik/zeit">Annahmen und Grenzen prüfen →</a></section>`;}
function avCalculationHTML(r){return r?`<strong>${r.flight.toLocaleString('de-CH',{maximumFractionDigits:2})} min</strong> rechnerische Flugzeit · <strong>${r.remaining.toLocaleString('de-CH',{maximumFractionDigits:2})} min</strong> nach Abzug der Vorbereitungszeit.<p>${r.exceeded?'Die angesetzte Vorbereitung verbraucht die ganze Modellfrist oder mehr.':'Die Zeitdifferenz ist positiv. Was praktisch innerhalb dieser Frist möglich wäre, bleibt zu prüfen.'}</p>`:'Bitte gültige Zahlen eingeben: 1–200 NM, 120–600 kt und 0–20 Minuten Vorbereitung.';}
function avTimeline(){return `<section class="section card"><span class="eyebrow">DRAMENTEXT · KEINE REALEN FLUGAUFZEICHNUNGEN</span><h2>Vier Zeitmarken, verschiedene Wissensstände</h2><div class="av-timeline">${[['19:32','Alarm','Die Räumungsfrage setzt bei einer frühen Warnung an.','35–41','evakuierung'],['19:48:12','SMS an Meiser','Die Nachricht berichtet einen Versuch der Passagiere. Ihr späteres Bekanntwerden beweist kein damaliges Wissen Kochs.','51–52, 68–71','meiser'],['20:21','Abschuss laut Anklage','Der Dramentext nennt Oberappersdorf und den 26. Mai 2013.','12','anklage'],['20:24','Erwarteter Einschlag','Dies ist die im Verfahren genannte Erwartung, kein tatsächlich beobachteter Einschlag.','35–41','evakuierung']].map(([t,h,b,p,id])=>`<article><time>${t}</time><h3>${h}</h3><p>${b}</p><a href="#lektuere/${id}">PDF-S. ${p} →</a></article>`).join('')}</div><p>Die Zeitmarken werden in der Zeitbasis des Textes wiedergegeben. Filmfassungen können abweichen. Keine nachträgliche Umrechnung in UTC ohne weitere Prüfung.</p>${note('aviatik-zeitlinie','Aviatik · Zeit und Wissen','Welche Information war wem zu welchem Zeitpunkt zugänglich? Welcher Beleg fehlt?')}</section>`;}
function avDispatch(){return `<section class="section card"><h2>Meldungswerkstatt</h2><p>Ein didaktisches Meldungsraster – kein echtes Funkprotokoll. Deine Eingaben bleiben im Journal.</p>${note('aviatik-beobachtung','Meldung · Beobachtung','Nur das Beobachtete, ohne unterstellte Absicht.')}${note('aviatik-quelle','Meldung · Quelle und Zeitpunkt','Wer oder welches System? Wann?')}${note('aviatik-unsicherheit','Meldung · Unsicherheit und Rückfrage','Was ist unklar und wie könnte man es prüfen?')}</section>`;}
let avEvents=false;
function initAviation(){if(!document.getElementById('av-root')?.dataset?.aviation||avEvents)return;avEvents=true;main.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.avLayer){const k=b.dataset.avLayer;document.getElementById('av-track').toggleAttribute('hidden',k==='position');document.getElementById('av-prediction').toggleAttribute('hidden',k!=='prediction');document.getElementById('av-layer-info').textContent=AV_LAYERS[k][1];main.querySelectorAll('[data-av-layer]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}if(b.dataset.avCheck){const u=AV_UNITS.find(x=>x.id===b.dataset.avCheck),n=Number(b.dataset.avOption);state.answers['aviatik-'+u.id]=n;save();document.getElementById('av-feedback-'+u.id).innerHTML=avQuizFeedback(u,n);main.querySelectorAll('[data-av-check="'+u.id+'"]').forEach(x=>x.setAttribute('aria-pressed',String(Number(x.dataset.avOption)===n)));}});main.addEventListener('input',e=>{if(e.target.id==='av-glossary-search')document.getElementById('av-glossary').innerHTML=avGlossary(e.target.value);if(e.target.hasAttribute('data-av-calc')){const ids=['av-distance','av-speed','av-delay'],values=ids.map(id=>{const raw=document.getElementById(id).value;return raw.trim()===''?NaN:Number(raw);});document.getElementById('av-calculation').innerHTML=avCalculationHTML(avCalculate(...values));}});}
